const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const defaults={amp:0,input:0,output:-12,gate:-60,gateOn:true,transpose:0,mode:'mono',doubler:12,doublerOn:false,gain:3,bass:5,mid:5,treble:6,presence:5,master:5,bloomOn:false,bloom:3,edgeOn:false,drive:2,tone:5,level:5,weightOn:false,boost:3,cab:0,micA:0,micB:1,posA:.45,posB:.6,distA:.1,distB:.25,micLevelA:0,micLevelB:-6,panA:-.3,panB:.3,eq:Array(9).fill(0),hp:60,lp:12000,delayOn:false,delayMix:18,delayTime:380,feedback:30,reverbOn:true,reverbMix:14,decay:2.5};
const ampInfo=[{name:'Porcelain',voice:'GLASSY / CLEAN',model:'P-01 · CLASS A',desc:'Open headroom. A little air. Every detail.',color:'clean',style:'Ivory Tolex',logo:'logo-ink.png'},{name:'Katana',voice:'PRECISE / METAL',model:'K-02 · HIGH GAIN',desc:'Fast attack. Tight lows. Unrelenting definition.',color:'metal',style:'Graphite',logo:'logo-cream.png'},{name:'Monolith',voice:'DENSE / THICK',model:'M-03 · LOW END',desc:'Weight, warmth, and a wall of sound.',color:'thick',style:'Moss Tweed',logo:'logo-cream.png'}];
const names=[['Porcelain Clean','Sunday Glass','Silver Springs','Velvet Morning','Open Horizon','Ivory Chords','Soft Focus','Bloom Theory','After the Rain','Moonlit Arpeggio','Studio Silk','Polished Edge','Cloud Nine','Amber Room','Electric Garden','Still Water','Neon Jazz','Chime District','Air & Light','Northern Sky','Warm Current','Dream Sequence','Last Light','Crystal Echo'],['Katana Rhythm','Iron Resolve','Precision Cut','Black Circuit','Drop Zone','Night Engine','Razor Bloom','Cold Steel','Zero Gravity','Red Horizon','Fracture Line','Machine Heart','Ghost Notes','Final Form','Electric Storm','Modern Ritual','Feral Lead','Obsidian Sky','Tectonic Shift','Signal Fire','Silent Thunder','Hard Reset','White Lightning','Aftershock'],['Monolith Wall','Gravity Well','Wool & Wire','Low Orbit','Desert Giant','Heavy Weather','Copper Sun','Stone Garden','Slow Burn','Velvet Hammer','Golden Furnace','Deep Current','Earth Mover','Midnight Fuzz','Thick as Thieves','Mammoth Steps','Warm Avalanche','Doom Bloom','Molten Core','Basement Ritual','Wide Awake','Dark Matter','Full Circle','Endless Sustain']];
const presets=names.flatMap((group,a)=>group.map((name,i)=>({id:`factory-${a*24+i}`,name,category:['Clean','Metal','Thick'][a],state:{...structuredClone(defaults),amp:a,gain:[2.2,7.2,6][a]+(i%5)*.4,bass:[4.5,5.3,7][a]+(i%3)*.3,mid:[5,3.8,6][a]+(i%4)*.35,treble:[6.4,6,4.6][a]-(i%3)*.25,presence:[5.5,6.5,4][a],cab:a,edgeOn:a===1,drive:a===1?1.5:2,weightOn:a===2&&i%3===0,boost:2+i%4,bloomOn:a===0&&i%3===1,delayOn:i%4===3,delayTime:280+i*13,reverbOn:a===0||i%5===0,reverbMix:10+(i%6)*3,doublerOn:i%6===4,eq:[0,0,(i%3)-1,0,(i%5)-2,0,0,0,0]}})));
