let state=structuredClone(presets[0].state),currentId=presets[0].id,view='amps',filter='All',dirty=false,midiAccess=null,learn=false,mappings={};
try{mappings=JSON.parse(localStorage.getItem('sishhin-midi')||'{}')}catch{}
const specs={input:['Input',-24,24,.1,'dB'],output:['Output',-36,6,.1,'dB'],gate:['Gate',-80,-20,1,'dB'],transpose:['Transpose',-12,12,1,'st'],doubler:['Doubler',5,30,.1,'ms'],gain:['Gain',0,10,.1,''],bass:['Bass',0,10,.1,''],mid:['Middle',0,10,.1,''],treble:['Treble',0,10,.1,''],presence:['Presence',0,10,.1,''],master:['Master',0,10,.1,''],bloom:['Sustain',0,10,.1,''],drive:['Drive',0,10,.1,''],tone:['Tone',0,10,.1,''],level:['Level',0,10,.1,''],boost:['Boost',0,10,.1,''],posA:['Position',0,1,.01,''],posB:['Position',0,1,.01,''],distA:['Distance',0,1,.01,''],distB:['Distance',0,1,.01,''],micLevelA:['Level',-24,6,.1,'dB'],micLevelB:['Level',-24,6,.1,'dB'],panA:['Pan',-1,1,.01,''],panB:['Pan',-1,1,.01,''],delayMix:['Mix',0,60,1,'%'],delayTime:['Time',60,1000,1,'ms'],feedback:['Feedback',0,80,1,'%'],reverbMix:['Mix',0,60,1,'%'],decay:['Decay',.3,7,.1,'s']};
function validPreset(p){return p&&typeof p.name==='string'&&p.name.length<=64&&p.state&&[0,1,2].includes(p.state.amp)}
function sanitize(s){const result=structuredClone(defaults);for(const [k,v] of Object.entries(s)){if(specs[k]&&Number.isFinite(v)){result[k]=Math.min(specs[k][2],Math.max(specs[k][1],v))}else if(typeof defaults[k]==='boolean'&&typeof v==='boolean')result[k]=v}for(const k of ['amp','cab','micA','micB'])if(Number.isInteger(s[k])&&s[k]>=0&&s[k]<=2)result[k]=s[k];if(['mono','stereo'].includes(s.mode))result.mode=s.mode;if(Array.isArray(s.eq)&&s.eq.length===9)result.eq=s.eq.map(v=>Number.isFinite(v)?Math.max(-12,Math.min(12,v)):0);for(const k of ['hp','lp'])if(Number.isFinite(s[k]))result[k]=Math.max(k==='hp'?20:3000,Math.min(k==='hp'?300:20000,s[k]));return result}
function presetUuid(){return globalThis.crypto?.randomUUID?.() || ('local-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2))}
function ampLogoSrc(filename){return window.sishhinNativeLogoUrls?.[filename] || 'assets/'+filename}
// Last-resort text fallback for restricted or damaged browser image decoders.
// Normal builds always render the supplied Japanese PNG (not this text).
document.addEventListener('error',event=>{
  const img=event.target;
  if(!(img instanceof HTMLImageElement)||!img.matches('img.amp-logo'))return;
  const fallback=document.createElement('span');
  fallback.className='amp-logo-fallback';
  fallback.textContent='失神';
  img.replaceWith(fallback);
},true);
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function format(k){let v=state[k],unit=specs[k][4];return (['input','output','micLevelA','micLevelB'].includes(k)&&v>0?'+':'')+(Number.isInteger(v)?v:v.toFixed(specs[k][3]<.1?2:1))+(unit?' '+unit:'')}
function knob(k,toggle){let [name,min,max,step]=specs[k];return `<div class="knob-wrap" data-knob="${k}"><div class="knob-top"><span class="knob-label">${name.toUpperCase()}</span>${toggle?`<button class="toggle ${state[toggle]?'on':''}" data-toggle="${toggle}" aria-label="${name} enabled" aria-pressed="${state[toggle]}"></button>`:''}</div><div class="knob" style="--rotation:${-135+(state[k]-min)/(max-min)*270}deg"><i></i><input type="range" aria-label="${name} ${k.endsWith('A')?'mic A':k.endsWith('B')?'mic B':''}" data-param="${k}" min="${min}" max="${max}" step="${step}" value="${state[k]}"></div><output class="knob-value">${format(k)}</output></div>`}
function refreshKnob(k){$$(`[data-knob="${k}"]`).forEach(el=>{el.querySelector('.knob').style.setProperty('--rotation',(-135+(state[k]-specs[k][1])/(specs[k][2]-specs[k][1])*270)+'deg');el.querySelector('input').value=state[k];el.querySelector('output').textContent=format(k)})}
function changed(){dirty=true;updatePresetLabel();engine.update(state)}
function setParam(k,v){state[k]=v;refreshKnob(k);changed()}
function controls(){for(const k of ['input','gate','transpose','doubler','output'])$(`#${k}-control`).innerHTML=knob(k,k==='gate'?'gateOn':k==='doubler'?'doublerOn':null);$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));updatePresetLabel()}
function updatePresetLabel(){const p=[...presets,...userPresets].find(p=>p.id===currentId);$('#preset-name').textContent=(p?.id.startsWith('factory')?String(presets.indexOf(p)+1).padStart(3,'0')+' · ':'')+(p?.name||'Custom sound')+(dirty?' *':'');$('#preset-count').textContent=presets.length+userPresets.length}
function render(){const info=ampInfo[state.amp];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const headings={amps:['01 / AMPLIFIER COLLECTION','A voice of your own.','ORIGINAL AMP MODEL'],pedals:['00 / BEFORE THE AMP','The first spark.','THREE DISTINCT CHARACTERS'],cabs:['02 / CABINET ROOM','Give your sound a home.','ALGORITHMIC CABINET VOICING'],eq:['03 / TONE SCULPTING','Every frequency, in its place.','±12 dB · NINE BANDS'],post:['04 / AFTER THE AMP','Leave something in the air.','DELAY + REVERB']};$('#view-kicker').textContent=headings[view][0];$('#view-title').textContent=headings[view][1];$('#view-note').innerHTML='<i></i>'+headings[view][2];let html='';
if(view==='amps')html=`<div class="amp-scene amp-v${state.amp+1}"><div class="amp-handle"></div><div class="amp"><div class="amp-face"><img class="amp-logo" data-logo="${info.logo}" src="${ampLogoSrc(info.logo)}" alt="失神 SISSHIN amplifier logo" draggable="false"><span class="amp-emblem">✧</span><span class="amp-model">${info.model}</span></div><div class="amp-controls"><div class="power-block"><div class="power-light"></div><span class="power-label">POWER</span></div>${['gain','bass','mid','treble','presence','master'].map(k=>knob(k)).join('')}</div></div><div class="amp-feet"><i></i><i></i></div><div class="amp-shadow"></div></div><div class="amp-description"><span>${info.style.toUpperCase()} · CUSTOM AMPLIFICATION</span><span>${info.desc}</span></div><div class="amp-cards">${ampInfo.map((a,i)=>`<button class="amp-card ${state.amp===i?'selected':''}" data-amp="${i}" aria-pressed="${state.amp===i}"><span class="mini-amp"></span><span><strong>${a.name}</strong><small>${a.voice}</small></span><i class="radio"></i></button>`).join('')}</div>`;
if(view==='pedals'||view==='post'){const pedals=view==='pedals'?[['BLOOM','OPTICAL COMPRESSOR','✺','bloomOn',['bloom']],['EDGE','DYNAMIC OVERDRIVE','⟐','edgeOn',['drive','tone','level']],['WEIGHT','LOW END BOOST','◈','weightOn',['boost']]]:[['ECHO','TAPE INSPIRED DELAY','≋','delayOn',['delayMix','delayTime','feedback']],['HALO','AMBIENT REVERB','◎','reverbOn',['reverbMix','decay']]];html=`<div class="pedalboard">${pedals.map(([n,sub,sign,t,ks])=>`<div class="pedal"><div class="pedal-sigil">${sign}</div><h3>${n}</h3><p>${sub}</p><div class="pedal-knobs">${ks.map(k=>knob(k)).join('')}</div><div class="pedal-led ${state[t]?'on':''}"></div><button class="footswitch" data-toggle="${t}" aria-label="${n} enabled" aria-pressed="${state[t]}"></button><div class="pedal-brand">SISSHIN</div></div>`).join('')}</div><p class="section-foot">${view==='pedals'?'A softer touch. A sharper edge. A little more weight.':'Space for the notes. A place for the silence.'}<br>Click a footswitch to engage. Drag a knob vertically to shape your sound.</p>`}
if(view==='eq'){const f=['65','125','250','500','1k','2k','4k','8k','16k'];html=`<div class="eq-panel">${f.map((f,i)=>`<label class="fader"><output id="eq-${i}">${state.eq[i]>0?'+':''}${state.eq[i]} dB</output><input type="range" aria-label="EQ ${f} Hz" data-eq="${i}" min="-12" max="12" step=".5" value="${state.eq[i]}"><span>${f} Hz</span></label>`).join('')}</div><div class="eq-actions"><label>HIGH PASS <select data-select="hp">${[20,40,60,80,100,120,160,200,300].map(v=>`<option value="${v}" ${state.hp===v?'selected':''}>${v} Hz</option>`).join('')}</select></label><label>LOW PASS <select data-select="lp">${[3000,5000,8000,10000,12000,16000,20000].map(v=>`<option value="${v}" ${state.lp===v?'selected':''}>${v/1000} kHz</option>`).join('')}</select></label><button id="reset-eq" class="subtle">Reset EQ</button></div><p class="section-foot">Sculpt the weight, bring out the detail, or make room in the mix.</p>`}
if(view==='cabs'){function mic(letter){return `<div class="mic-panel"><h3>MIC ${letter} <span class="eyebrow"> / ${letter==='A'?'CLOSE':'ROOM'}</span></h3><select data-select="mic${letter}" aria-label="Microphone ${letter}">${['Dynamic 57','Ribbon 121','Condenser 87'].map((n,i)=>`<option value="${i}" ${state['mic'+letter]===i?'selected':''}>${n}</option>`).join('')}</select><div class="mic-knobs">${['pos','dist','micLevel','pan'].map(k=>knob(k+letter)).join('')}</div></div>`}html=`<div class="cab-layout">${mic('A')}<div class="cabinet"><span class="cab-badge">SISSHIN</span><div class="speaker"></div><div class="speaker"></div></div>${mic('B')}</div><div class="cab-select">${['1×12 · Open','4×12 · Modern','2×12 · Oversized'].map((n,i)=>`<button data-cab="${i}" class="${state.cab===i?'active':''}">${n}</button>`).join('')}</div><p class="section-foot">Blend two microphone voicings. Position moves from the center to the edge.</p>`}
$('#view-content').innerHTML=html;
if(view==='cabs'&&window.SISHHIN_NATIVE){
 $('#view-content').insertAdjacentHTML('beforeend',`<div class="native-ir-control"><div><b>CUSTOM CABINET IR</b><small id="native-ir-label">Algorithmic cabinet active · No custom IR loaded</small></div><div><button class="subtle" data-ir="load">Load WAV / AIFF</button><button class="text-button" data-ir="clear">Clear</button></div></div>`);
}}

let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function applyPreset(p){state=sanitize(p.state);currentId=p.id;dirty=false;controls();render();engine.update(state);toast(p.name+' loaded')}
function presetList(){const q=$('#preset-search').value.toLowerCase();$('#preset-list').innerHTML=[...presets,...userPresets].filter(p=>(filter==='All'||p.category===filter)&&p.name.toLowerCase().includes(q)).map(p=>`<div class="preset-row ${p.id===currentId?'chosen':''}"><button data-preset="${p.id}" style="flex:1;text-align:left">${esc(p.name)}</button><small>${p.category==='User'?'USER':p.category.toUpperCase()}</small>${p.category==='User'?`<button class="delete-preset" data-delete="${p.id}" aria-label="Delete ${esc(p.name)}">×</button>`:''}</div>`).join('')||'<p>No presets found. Try another search.</p>'}
function storePresets(){try{localStorage.setItem('sishhin-presets',JSON.stringify(userPresets));return true}catch{toast('Browser storage is full. Export your presets to keep them.');return false}}
document.addEventListener('input',e=>{if(e.target.dataset.param)setParam(e.target.dataset.param,+e.target.value);if(e.target.dataset.eq!==undefined){let i=+e.target.dataset.eq;state.eq[i]=+e.target.value;$('#eq-'+i).textContent=(state.eq[i]>0?'+':'')+state.eq[i]+' dB';changed()}});
document.addEventListener('change',e=>{if(e.target.dataset.select){state[e.target.dataset.select]=+e.target.value;changed()}});
let drag=null;document.addEventListener('pointerdown',e=>{const k=e.target.dataset.param;if(!k)return;e.preventDefault();drag={k,y:e.clientY,v:state[k],id:e.pointerId,target:e.target};e.target.setPointerCapture(e.pointerId);e.target.focus()});document.addEventListener('pointermove',e=>{if(!drag)return;let [_,min,max,step]=specs[drag.k];let v=Math.max(min,Math.min(max,Math.round((drag.v+(drag.y-e.clientY)*(max-min)/(e.shiftKey?1200:180))/step)*step));setParam(drag.k,+v.toFixed(3))});document.addEventListener('pointerup',()=>drag=null);document.addEventListener('pointercancel',()=>drag=null);document.addEventListener('dblclick',e=>{if(e.target.dataset.param)setParam(e.target.dataset.param,defaults[e.target.dataset.param])});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.view){view=d.view;render()}if(d.ir==='load')window.sishhinNativeEmit('sishhinIR',{});if(d.ir==='clear')window.sishhinNativeEmit('sishhinClearIR',{});if(d.amp!==undefined){
    const selected=+d.amp;
    if(selected!==state.amp && selected>=0 && selected<3){
      // Each head starts from its characteristic gain and pedal voicing,
      // without carrying an old metal boost onto the clean amplifier.
      // Global input/output, MIDI, and post effects stay intact.
      const voice=presets[selected*24].state;
      for(const key of ['amp','gain','bass','mid','treble','presence','cab',
                         'edgeOn','weightOn','bloomOn','drive','boost'])
        state[key]=voice[key];
      changed();render();
    }
  }if(d.cab!==undefined){state.cab=+d.cab;changed();render()}if(d.toggle){state[d.toggle]=!state[d.toggle];changed();controls();render()}if(d.mode){state.mode=d.mode;changed();controls()}if(d.preset){applyPreset([...presets,...userPresets].find(p=>p.id===d.preset));$('#presets-dialog').close()}if(d.filter){filter=d.filter;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));presetList()}if(d.delete){userPresets=userPresets.filter(p=>p.id!==d.delete);storePresets();presetList();updatePresetLabel()}if(b.classList.contains('close'))b.closest('dialog').close()});
$('#preset-open').onclick=()=>{presetList();$('#presets-dialog').showModal()};$('#preset-search').oninput=presetList;
for(const [id,dir] of [['prev',-1],['next',1]])$('#'+id).onclick=()=>{const all=[...presets,...userPresets];let i=all.findIndex(p=>p.id===currentId);applyPreset(all[(i+dir+all.length)%all.length])};
$('#save').onclick=()=>{$('#save-dialog').showModal();$('#save-name').focus()};$('#save-form').onsubmit=e=>{e.preventDefault();const name=$('#save-name').value.trim();if(!name)return;const p={id:'user-'+presetUuid(),name,category:'User',state:structuredClone(state)};userPresets.push(p);if(!storePresets()){userPresets.pop();return}currentId=p.id;dirty=false;updatePresetLabel();$('#save-dialog').close();toast('Preset saved to this browser')};
$('#export-presets').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,presets:userPresets},null,2)],{type:'application/json'}));a.download='sishhin-presets.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('#import-presets').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error();const data=JSON.parse(await file.text());if(!Array.isArray(data.presets)||data.presets.length>500||!data.presets.every(validPreset))throw Error();const imported=data.presets.map(p=>({id:'user-'+presetUuid(),name:p.name,category:'User',state:sanitize(p.state)}));userPresets.push(...imported);storePresets();presetList();updatePresetLabel();toast(imported.length+' presets imported')}catch{toast('Choose a valid SishhinDSP preset export.')}e.target.value=''};
document.addEventListener('click',e=>{if(e.target.id==='reset-eq'){state.eq=Array(9).fill(0);state.hp=60;state.lp=12000;changed();render()}});
const engine=window.SISHHIN_NATIVE?new SishhinNativeAudio():new SishhinAudio();
async function start(mode){if(window.SISHHIN_NATIVE){toast('Guitar audio enters through the DAW or standalone audio device settings.');return}$('#demo').disabled=true;$('#connect').disabled=true;try{if(engine.sourceMode===mode){engine.stop();setAudioStatus();return}await engine.start(mode,state);setAudioStatus();toast(mode==='demo'?'Synthesized guitar loop playing':'Guitar input connected — use headphones')}catch(e){toast(e.name==='NotAllowedError'?'Audio input permission was denied. You can still play the demo.':'Could not start audio: '+e.message);setAudioStatus()}finally{$('#demo').disabled=false;$('#connect').disabled=false}}
function setAudioStatus(){if(window.SISHHIN_NATIVE){$('#audio-status').textContent='Native audio ready';$('#status-led').classList.add('live');$('#sample-rate').textContent=(engine.ctx.sampleRate/1000).toFixed(1)+' kHz';return}const m=engine.sourceMode;$('#audio-status').textContent=m==='demo'?'Demo playing':m==='live'?'Input connected':'Audio offline';$('#status-led').classList.toggle('live',!!m);$('#demo').innerHTML=m==='demo'?'Ⅱ <span>Stop demo</span>':'▷ <span>Play demo</span>';$('#connect').textContent=m==='live'?'■ Disconnect':'↳ Connect guitar';$('#sample-rate').textContent=m?engine.ctx.sampleRate/1000+' kHz':'WEB AUDIO'}
$('#demo').onclick=()=>start('demo');$('#connect').onclick=()=>start('live');$('#tuner-open').onclick=()=>$('#tuner-dialog').showModal();$('#tuner-mute').onclick=()=>{engine.muted=!engine.muted;engine.update(state);$('#tuner-mute').textContent=engine.muted?'Unmute output':'Mute output while tuning'};$('#tuner-dialog').addEventListener('close',()=>{engine.muted=false;engine.update(state);$('#tuner-mute').textContent='Mute output while tuning'});
$('#midi-param').innerHTML=Object.entries(specs).map(([k,s])=>`<option value="${k}">${s[0]}${k.endsWith('A')?' · Mic A':k.endsWith('B')?' · Mic B':''}</option>`).join('');
function renderMappings(){$('#midi-mappings').innerHTML=Object.entries(mappings).map(([cc,k])=>`CC ${cc} → ${esc(specs[k]?.[0]||k)} <button data-unmap="${cc}">Remove</button><br>`).join('')||'<p>No CC mappings yet.</p>'}
$('#midi-open').onclick=()=>{renderMappings();$('#midi-dialog').showModal()};$('#midi-enable').onclick=async()=>{if(window.SISHHIN_NATIVE){$('#midi-status').textContent='DAW MIDI is connected to the VST3 input. Move a CC controller or send Program Change.';return}try{if(!navigator.requestMIDIAccess)throw Error('This browser does not support Web MIDI. Try Chrome or Edge.');midiAccess=await navigator.requestMIDIAccess({sysex:false});function bind(){let n=0;for(const input of midiAccess.inputs.values()){n++;input.onmidimessage=onMidi}$('#midi-status').textContent=n?n+' MIDI input(s) connected.':'MIDI enabled. Connect a USB MIDI controller.'}midiAccess.onstatechange=bind;bind()}catch(e){$('#midi-status').textContent=e.message}};
$('#midi-learn').onclick=()=>{if(!midiAccess&&!window.SISHHIN_NATIVE){toast('Enable MIDI access first');return}learn=true;$('#midi-learn').textContent='Move a controller…'};
function onMidi(e){const [status,cc,value]=e.data;const type=status&240;if(type===192){applyPreset(presets[cc%presets.length]);return}if(type!==176)return;if(learn){mappings[cc]=$('#midi-param').value;learn=false;$('#midi-learn').textContent='Learn next CC';try{localStorage.setItem('sishhin-midi',JSON.stringify(mappings))}catch{}renderMappings();toast('CC '+cc+' mapped')}const k=mappings[cc];if(specs[k]){const [_,min,max,step]=specs[k];setParam(k,+(Math.round((min+(max-min)*value/127)/step)*step).toFixed(3))}}
$('#midi-mappings').onclick=e=>{if(e.target.dataset.unmap!==undefined){delete mappings[e.target.dataset.unmap];try{localStorage.setItem('sishhin-midi',JSON.stringify(mappings))}catch{}renderMappings()}};
setInterval(()=>{if(!engine.ctx||!engine.sourceMode){$('#meter-level').style.width='0%';return}const level=engine.level();$('#meter-level').style.width=Math.min(100,level*300)+'%';if($('#tuner-dialog').open){const f=engine.pitch();if(f){const n=Math.round(69+12*Math.log2(f/440)),ideal=440*Math.pow(2,(n-69)/12),cents=Math.round(1200*Math.log2(f/ideal));$('#tuner-note').textContent=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][((n%12)+12)%12]+(Math.floor(n/12)-1);$('#tuner-info').textContent=f.toFixed(1)+' Hz · '+(cents>0?'+':'')+cents+' cents';$('#tuner-needle').style.left=(50+cents*.9)+'%'}else{$('#tuner-note').textContent='—';$('#tuner-info').textContent='Play a single sustained note.'}}},100);
controls();render();

// JUCE-initiated updates do not echo back as new host automation messages.
window.sishhinNativeApplyState=(nativeState)=>{
  if(!window.SISHHIN_NATIVE||!nativeState)return;
  state=sanitize(nativeState); controls();render();
};
window.sishhinNativeMidi=(status,number,value)=>onMidi({data:[status,number,value]});
window.sishhinNativePulse=(level,sampleRate,pitch,irName,inputPeak,activeAmp)=>{
  if(!window.SISHHIN_NATIVE)return;
  engine.nativeLevel=level;engine.nativePitch=pitch;engine.ctx.sampleRate=sampleRate||48000;
  const voiceLabels=['CLEAN','METAL','THICK'];
  const active=voiceLabels[activeAmp] || 'UNKNOWN';
  $('#sample-rate').textContent=((sampleRate||48000)/1000).toFixed(1)+' kHz · '+
    active+' · '+(inputPeak>0.0003?'INPUT OK':'NO INPUT');
  const label=$('#native-ir-label');
  if(label)label.textContent=irName?'Loaded: '+irName:'Algorithmic cabinet active · No custom IR loaded';
};
if(window.SISHHIN_NATIVE){
  document.body.classList.add('native-mode');
  $('#demo').disabled=true;$('#demo').title='Demo available in the website edition';
  $('#connect').textContent='↳ DAW / SYSTEM INPUT';
  $('#connect').title='DAW audio inputs or standalone audio settings provide the guitar signal';
  $('.prototype-note').textContent='Native engine · VST3 / Standalone · For lowest latency use your audio interface and headphones.';
  $('#midi-enable').textContent='Using DAW MIDI input';
  setAudioStatus();
  window.sishhinNativeAnnounceReady();
}
